import * as d3 from 'd3';
import { range } from 'd3';
import { useMemo } from 'react';

// ---- inlined from solarTerminator ----
// NOAA solar-position formulae, ported from the solar-calculator package the notebook
// required. Angles are degrees unless noted; `t` is Julian centuries since J2000.0.

const RAD = Math.PI / 180;
const DEG = 180 / Math.PI;

const century = (ms: number) => (ms - Date.UTC(2000, 0, 1, 12)) / 3.15576e12;

function meanLongitude(t: number): number {
  const l = (280.46646 + t * (36000.76983 + t * 0.0003032)) % 360;
  return l < 0 ? l + 360 : l;
}

const meanAnomaly = (t: number) => 357.52911 + t * (35999.05029 - 0.0001537 * t);

const eccentricity = (t: number) => 0.016708634 - t * (0.000042037 + 0.0000001267 * t);

function equationOfCenter(t: number): number {
  const m = meanAnomaly(t) * RAD;
  return (
    Math.sin(m) * (1.914602 - t * (0.004817 + 0.000014 * t)) +
    Math.sin(2 * m) * (0.019993 - 0.000101 * t) +
    Math.sin(3 * m) * 0.000289
  );
}

function apparentLongitude(t: number): number {
  const nutation = 0.00478 * Math.sin((125.04 - 1934.136 * t) * RAD);
  return meanLongitude(t) + equationOfCenter(t) - 0.00569 - nutation;
}

function obliquity(t: number): number {
  const mean = 23 + (26 + (21.448 - t * (46.815 + t * (0.00059 - t * 0.001813))) / 60) / 60;
  return mean + 0.00256 * Math.cos((125.04 - 1934.136 * t) * RAD);
}

function declination(t: number): number {
  return (
    Math.asin(Math.sin(obliquity(t) * RAD) * Math.sin(apparentLongitude(t) * RAD)) * DEG
  );
}

/** Apparent minus mean solar time, in minutes. 15 degrees of longitude per hour, so /4 gives degrees. */
function equationOfTime(t: number): number {
  const e = eccentricity(t);
  const m = meanAnomaly(t) * RAD;
  const l = meanLongitude(t) * RAD;
  const y = Math.tan((obliquity(t) * RAD) / 2) ** 2;
  return (
    (y * Math.sin(2 * l) -
      2 * e * Math.sin(m) +
      4 * e * y * Math.sin(m) * Math.cos(2 * l) -
      0.5 * y * y * Math.sin(4 * l) -
      1.25 * e * e * Math.sin(2 * m)) *
    DEG *
    4
  );
}

/** The [longitude, latitude] where the sun is directly overhead at the given UTC instant. */
function subsolarPoint(ms: number): [number, number] {
  const t = century(ms);
  const dayStart = new Date(ms).setUTCHours(0, 0, 0, 0);
  const solarNoonLongitude = ((dayStart - ms) / 864e5) * 360 - 180;
  const longitude = solarNoonLongitude - equationOfTime(t) / 4;
  return [((((longitude + 180) % 360) + 360) % 360) - 180, declination(t)];
}

// ---- inlined from solarPath ----
// Sun paths across the sky dome for one fixed place, computed from closed-form astronomy.
// The subsolar point already carries declination and the equation of time, so this module
// only converts it into the observer's horizontal coordinates.



const RAD_solarPath = Math.PI / 180;
const DEG_solarPath = 180 / Math.PI;

const LOCATION = {
  name: 'San Francisco',
  latitude: 37.7749,
  longitude: -122.4194,
  // A fixed standard-time offset all year: on a daylight-saving clock the hour loops below
  // would jump an hour mid-year and stop being single closed curves.
  utcOffset: -8,
  zone: 'PST'
};

const YEAR = 2026;

/** Azimuth clockwise from north, altitude above the horizon. Both in degrees. */
type Sky = { azimuth: number; altitude: number };

function sunSky(ms: number): Sky {
  const [sunLongitude, declinationDegrees] = subsolarPoint(ms);
  // Hour angle is zero when the sun stands over the observer's meridian, positive after.
  const hourAngle = (((LOCATION.longitude - sunLongitude + 540) % 360) - 180) * RAD_solarPath;
  const latitude = LOCATION.latitude * RAD_solarPath;
  const declination = declinationDegrees * RAD_solarPath;

  const altitude = Math.asin(
    Math.sin(latitude) * Math.sin(declination) +
      Math.cos(latitude) * Math.cos(declination) * Math.cos(hourAngle)
  );
  const azimuth = Math.atan2(
    -Math.cos(declination) * Math.sin(hourAngle),
    Math.cos(latitude) * Math.sin(declination) -
      Math.sin(latitude) * Math.cos(declination) * Math.cos(hourAngle)
  );

  return { azimuth: (azimuth * DEG_solarPath + 360) % 360, altitude: altitude * DEG_solarPath };
}

/** Split a sample sequence into the contiguous runs sitting at or above the horizon. */
function aboveHorizon(samples: Sky[]): Sky[][] {
  const runs: Sky[][] = [];
  let run: Sky[] = [];
  for (const sample of samples) {
    if (sample.altitude >= 0) {
      run.push(sample);
      continue;
    }
    if (run.length > 1) runs.push(run);
    run = [];
  }
  if (run.length > 1) runs.push(run);
  return runs;
}

const localMidnight = (month: number, day: number) =>
  Date.UTC(YEAR, month, day) - LOCATION.utcOffset * 3600e3;

type DateCurve = { key: string; declination: number; runs: Sky[][] };

// The 21st of each month, paired by the declination shared either side of a solstice: the
// two dates of a pair trace the same arc, so only the first of each pair is sampled.
const DATES: [number, string][] = [
  [5, 'Jun 21'],
  [4, 'May / Jul'],
  [3, 'Apr / Aug'],
  [2, 'Mar / Sep'],
  [1, 'Feb / Oct'],
  [0, 'Jan / Nov'],
  [11, 'Dec 21']
];

const dateCurves: DateCurve[] = DATES.map(([month, key]) => {
  const midnight = localMidnight(month, 21);
  return {
    key,
    declination: subsolarPoint(midnight + 12 * 3600e3)[1],
    runs: aboveHorizon(range(0, 24 * 60 + 1, 4).map((m) => sunSky(midnight + m * 60e3)))
  };
});

type HourCurve = { hour: number; runs: Sky[][] };

// One clock hour sampled right around the year traces an analemma: the figure eight the sun
// makes at a fixed clock time, from the axial tilt beating against the orbit's ellipse.
const hourCurves: HourCurve[] = range(5, 20).map((hour) => {
  const days = range(0, 366, 5);
  const samples = [...days, days[0]].map((day) =>
    sunSky(localMidnight(0, 1) + day * 864e5 + hour * 3600e3)
  );
  return { hour, runs: aboveHorizon(samples) };
});

// The sky dome seen from below: a 90-degree cap on the zenith, so its rim is the horizon.
const HORIZON = d3.geoCircle().radius(90).center([0, 90])();

const ALTITUDES = [15, 30, 45, 60, 75];
const SPOKES = d3.range(0, 360, 15);
const CARDINALS: Record<number, string> = { 0: 'N', 90: 'E', 180: 'S', 270: 'W' };

// Plasma's dark end vanishes against the panel, so the ramp starts a third of the way in.
const color = d3.scaleSequential([-23.44, 23.44], (t) => d3.interpolatePlasma(0.35 + t * 0.55));

/** The sample of highest, or with sign -1 lowest, altitude across a curve's runs. */
function extreme(runs: Sky[][], sign: number): Sky | null {
  const points = runs.flat();
  if (points.length === 0) return null;
  return points.reduce((best, s) => (sign * s.altitude > sign * best.altitude ? s : best));
}

export default function SolarPath({ width }: { width: number }) {
  // The compass ring sits 3.6 percent of the dome outside the horizon, so its room has to
  // scale with the dome; the constant is the text beyond it.
  const side = Math.round(width * 0.035) + 14;
  const size = Math.max(width - side * 2, 0);
  const height = size + side * 2 + 22;

  const sky = useMemo(() => {
    if (size <= 0) return null;

    const projection = d3
      .geoStereographic()
      .reflectY(true)
      .rotate([0, -90])
      .precision(0.2)
      .fitSize([size, size], HORIZON);
    const [cx, cy] = projection.translate();

    // No clip angle is set, so every finite azimuth and altitude projects; the fallback
    // only satisfies the nullable call signature.
    const project = (s: Sky): [number, number] =>
      projection([s.azimuth, s.altitude]) ?? [cx, cy];

    const line = d3.line();
    const draw = (runs: Sky[][]) => runs.map((run) => line(run.map(project)) ?? '').join(' ');
    const radius = (altitude: number) => Math.abs(project({ azimuth: 0, altitude })[1] - cy);

    const dates = dateCurves.map((c) => {
      const noon = extreme(c.runs, 1);
      return {
        key: c.key,
        d: draw(c.runs),
        stroke: color(c.declination),
        label: noon && project(noon)
      };
    });

    // An analemma is labelled at its lowest point, on the December arc, where the loops fan
    // widest apart. The ones grazing the horizon have no room and go unlabelled.
    const hours = hourCurves.map((c) => {
      const low = extreme(c.runs, -1);
      return {
        key: c.hour,
        d: draw(c.runs),
        label: low && low.altitude > 3 ? project(low) : null
      };
    });

    // June and July crest within a few pixels of each other near the zenith, so each label
    // is pushed down off the one inside it until the stack is legible.
    let taken = -Infinity;
    for (const date of dates) {
      if (!date.label) continue;
      date.label[1] = Math.max(date.label[1], taken + 12);
      taken = date.label[1];
    }

    return {
      cx,
      cy,
      horizon: radius(0),
      rings: ALTITUDES.map((altitude) => ({ altitude, r: radius(altitude) })),
      spokes: SPOKES.map((azimuth) => ({ azimuth, end: project({ azimuth, altitude: 0 }) })),
      ticks: d3.range(0, 360, 5).map((azimuth) => ({
        azimuth,
        from: project({ azimuth, altitude: 0 }),
        to: project({ azimuth, altitude: azimuth % 15 ? -1 : -2 })
      })),
      compass: d3.range(0, 360, 30).map((azimuth) => ({
        azimuth,
        at: project({ azimuth, altitude: -4 }),
        text: CARDINALS[azimuth] ?? `${azimuth}°`
      })),
      dates,
      hours
    };
  }, [size]);

  if (width === 0 || !sky) return null;

  const showHours = size >= 420;
  // The caption is the widest thing in the frame, so it sheds clauses before it can overrun.
  const caption =
    size >= 560
      ? `${LOCATION.name} (37.8°N, 122.4°W), ${YEAR}. Arcs are the 21st of each month, loops each ${LOCATION.zone} hour.`
      : size >= 300
        ? `${LOCATION.name}, ${YEAR}. Monthly arcs, hourly analemmas.`
        : `${LOCATION.name}, ${YEAR}`;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Sky dome over ${LOCATION.name} in ${YEAR}, looking up: the horizon is the outer circle and the zenith the centre. Seven arcs trace the sun's path on the 21st of each month, from a 75.7 degree noon in June down to 28.8 degrees in December, crossed by the analemma loops each ${LOCATION.zone} clock hour makes over the year.`}
    >
      <g transform={`translate(${side},${side})`}>
        <g fill="none" stroke="var(--line)">
          {sky.rings.map((r) => (
            <circle key={r.altitude} cx={sky.cx} cy={sky.cy} r={r.r} />
          ))}
          {sky.spokes.map((s) => (
            <line key={s.azimuth} x1={sky.cx} y1={sky.cy} x2={s.end[0]} y2={s.end[1]} />
          ))}
        </g>
        <g stroke="var(--muted)">
          <circle cx={sky.cx} cy={sky.cy} r={sky.horizon} fill="none" strokeWidth={1.2} />
          {sky.ticks.map((t) => (
            <line key={t.azimuth} x1={t.from[0]} y1={t.from[1]} x2={t.to[0]} y2={t.to[1]} />
          ))}
        </g>

        <g fill="none" stroke="var(--muted)" strokeWidth={1} strokeOpacity={0.55}>
          {sky.hours.map((h) => (
            <path key={h.key} d={h.d} />
          ))}
        </g>
        <g fill="none" strokeWidth={1.8} strokeLinejoin="round">
          {sky.dates.map((c) => (
            <path key={c.key} d={c.d} stroke={c.stroke} />
          ))}
        </g>

        <g
          textAnchor="middle"
          stroke="var(--bg)"
          strokeWidth={3}
          paintOrder="stroke"
          fontSize={10}
        >
          {sky.compass.map((c) => (
            <text
              key={c.azimuth}
              x={c.at[0]}
              y={c.at[1]}
              dy="0.35em"
              fill={CARDINALS[c.azimuth] ? 'var(--text)' : 'var(--muted)'}
              fontWeight={CARDINALS[c.azimuth] ? 600 : undefined}
            >
              {c.text}
            </text>
          ))}
          {sky.rings.map((r) => (
            <text key={r.altitude} x={sky.cx} y={sky.cy - r.r} dy="0.35em" fill="var(--muted)">
              {r.altitude}°
            </text>
          ))}
          {showHours &&
            sky.hours.map(
              (h) =>
                h.label && (
                  <text key={h.key} x={h.label[0]} y={h.label[1] + 14} fill="var(--muted)" fontSize={9}>
                    {h.key}
                  </text>
                )
            )}
          {size >= 340 &&
            sky.dates.map(
              (c) =>
                c.label && (
                  <text key={c.key} x={c.label[0]} y={c.label[1] - 7} fill={c.stroke}>
                    {c.key}
                  </text>
                )
            )}
        </g>
      </g>
      <text x={side} y={height - 8} fill="var(--muted)" fontSize={11}>
        {caption}
      </text>
    </svg>
  );
}
